namespace sv_2b28c6ba13184b418d3fc687759ab51d.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly List<string> TimeSlots =
        ["9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM", "11:00 AM", "1:00 PM", "1:30 PM", "2:00 PM", "2:30 PM", "3:00 PM"];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return all slots for any valid doctor+date combination
        return Task.FromResult(new List<string>(TimeSlots));
    }

    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentStep2Model.Doctor)] = []; // ensure key order
            errors[nameof(AppointmentStep1Model.Email)] = ["Account has outstanding balance"];
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors.TryAdd(nameof(AppointmentStep2Model.Doctor), []);
            errors[nameof(AppointmentStep2Model.Doctor)] =
                [.. errors[nameof(AppointmentStep2Model.Doctor)], "Selected doctor does not accept self-pay patients"];
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentStep2Model.TimeSlot)] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

public class AppointmentStep1Model
{
    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required.")]
    [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone number is required.")]
    public string? Phone { get; set; }

    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }
}

public class AppointmentStep2Model
{
    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a doctor.")]
    public string? Doctor { get; set; }

    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required.")]
    public DateOnly? Date { get; set; }

    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a time slot.")]
    public string? TimeSlot { get; set; }

    [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required.")]
    [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string? Reason { get; set; }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_2b28c6ba13184b418d3fc687759ab51d.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_2b28c6ba13184b418d3fc687759ab51d.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

@* ───── STEP 1 ───── *@
<EditForm EditContext="step1Context" OnValidSubmit="HandleStep1Valid" FormName="step1">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label class="form-label">Patient Name</label>
        <InputText class="form-control" @bind-Value="step1.PatientName" />
        <ValidationMessage For="() => step1.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <InputText class="form-control" @bind-Value="step1.Email" />
        <ValidationMessage For="() => step1.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone</label>
        <InputText class="form-control" @bind-Value="step1.Phone" />
        <ValidationMessage For="() => step1.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Insurance Provider</label>
        <InputSelect class="form-select" @bind-Value="step1.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => step1.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="submit" class="btn btn-primary">Next</button>
    }
</EditForm>

@* ───── STEP 2 ───── *@
@if (showStep2)
{
    <hr />
    <h4>Appointment Details</h4>

    <EditForm EditContext="step2Context" OnValidSubmit="HandleStep2Valid" FormName="step2">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        <div class="mb-3">
            <label class="form-label">Preferred Doctor</label>
            <InputSelect class="form-select" @bind-Value="step2.Doctor">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => step2.Doctor" />
        </div>

        <div class="mb-3">
            <label class="form-label">Date</label>
            <InputDate class="form-control" @bind-Value="step2.Date" @bind:after="OnDateChanged" />
            <ValidationMessage For="() => step2.Date" />
            @if (step2.Date.HasValue && step2.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
            {
                <div class="text-danger">Date must be in the future.</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Time Slot</label>
            <InputSelect class="form-select" @bind-Value="step2.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in availableSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => step2.TimeSlot" />
        </div>

        <div class="mb-3">
            <label class="form-label">Reason for Visit</label>
            <InputTextArea class="form-control" @bind-Value="step2.Reason" rows="3" />
            <ValidationMessage For="() => step2.Reason" />
        </div>

        <button type="submit" class="btn btn-success me-2" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
        <button type="button" class="btn btn-secondary" @onclick="GoBackToStep1">Back</button>
    </EditForm>
}

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-3">Appointment booked successfully!</div>
}

@code {
    private AppointmentStep1Model step1 = new();
    private AppointmentStep2Model step2 = new();
    private EditContext step1Context = default!;
    private EditContext step2Context = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool bookingConfirmed;
    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        step1Context = new EditContext(step1);
        step2Context = new EditContext(step2);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void HandleStep1Valid()
    {
        showStep2 = true;
    }

    private async Task OnDateChanged()
    {
        if (step2.Doctor is not null && step2.Date.HasValue && step2.Date.Value > DateOnly.FromDateTime(DateTime.Today))
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(step2.Doctor, step2.Date.Value);
        }
        else
        {
            availableSlots = [];
        }
        step2.TimeSlot = null;
    }

    private async Task HandleStep2Valid()
    {
        if (step2.Date.HasValue && step2.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            return; // future-date guard
        }

        isSubmitting = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                step1.Email!, step1.InsuranceProvider!, step2.Doctor!, step2.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            bookingConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void GoBackToStep1()
    {
        showStep2 = false;
        bookingConfirmed = false;
    }
}

