+                step1.Email!, step1.InsuranceProvider!, step2.Doctor!, step2.TimeSlot!);
+
+            if (errors.Count > 0)
+            {
+                var s1Errors = new Dictionary<string, List<string>>();
+                var s2Errors = new Dictionary<string, List<string>>();
+
+                foreach (var (field, messages) in errors)
+                {
+                    if (Step1Fields.Contains(field))
+                        s1Errors[field] = messages;
+                    else
+                        s2Errors[field] = messages;
+                }
+
+                if (s1Errors.Count > 0)
+                    step1Validator!.DisplayErrors(s1Errors);
+                if (s2Errors.Count > 0)
+                    step2Validator!.DisplayErrors(s2Errors);
+
+                return;
+            }
+
+            bookingConfirmed = true;
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
+    private void GoBackToStep1()
+    {
+        showStep2 = false;
+        bookingConfirmed = false;
+    }
+}
